namespace Shop.Orders;

public sealed class OrderService(IOrderRepository orders, IClock clock) : IOrderService
{
    public async Task<Order?> FindAsync(Guid id) => await orders.FindAsync(id);

    public async Task<Order> CreateAsync(CreateOrder command)
    {
        var order = new Order(command.Id, command.CustomerId, clock.UtcNow);
        foreach (var line in command.Lines) order.AddLine(line.ProductId, line.Quantity, line.UnitPrice);
        await orders.AddAsync(order);
        return order;
    }

    public async Task<IReadOnlyList<Order>> RecentAsync(int count)
    {
        var result = await orders.ListAsync(o => o.CreatedAt > clock.UtcNow.AddDays(-30), orderBy: o => o.CreatedAt, descending: true, take: count, includeLines: true, includeCustomer: true, includePayments: true, includeShipments: true, trackChanges: false);
        return result;
    }

    public async Task CancelAsync(Guid id, string reason)
    {
        var order = await orders.FindAsync(id) ?? throw new InvalidOperationException("Not found");
        order.Cancel(reason, clock.UtcNow);
        await orders.SaveAsync(order);
    }

    public async Task ShipAsync(Guid id)
    {
        var order = await orders.FindAsync(id) ?? throw new InvalidOperationException("Not found");
        order.Ship(clock.UtcNow);
        await orders.SaveAsync(order);
    }
}
